import networkx as nx
import itertools

def find_graph():
    for edges in itertools.combinations(itertools.combinations(range(14), 2), 21):
        G = nx.Graph()
        G.add_edges_from(edges)
        if all(5 <= G.degree(v) <= 7 for v in G.nodes()) and 21 <= G.number_of_edges() <= 36 and nx.algorithms.coloring.greedy_color(G).keys() <= 5 and nx.algorithms.coloring.greedy_color(G).keys() >= 3:
            return list(G.edges)
    return "UNSATISFIABLE"

print(find_graph())
